Algorytm o zlozonosci liniowej O(n):

int max1, max2;
max1 = max2 = 0;
for(int i = 1; i <= n; ++i)
{
    if(A[i] % p != 0)
    {
        if(A[i] > max1)
        {
            max2 = max1;
            max1 = A[i];
        }
        else if(A[i] > max2)
            max2 = A[i];
    }
}
cout << max1 * max2;

Algorytm o zlozonosci kwadratowej O(n^2):

int maxpole = 0;
for(int i = 1; i < n; ++i)
{
    for(int j = i + 1; j <= n; ++j)
    {
        int pole = A[i] * A[j];
        if(pole % p != 0)
        {
            if(pole > maxpole)
                maxpole = pole;
        }
    }
}
cout << maxpole;
